      color: '#333',
      borderBottom: '2px solid #eee',
      paddingBottom: '10px',
    },
    cartContainer: {
      display: 'flex',
      flexDirection: 'row' as 'row',
      gap: '30px',
      flexWrap: 'wrap' as 'wrap',
    },
    cartItems: {
      flex: '1 1 65%',
      minWidth: '300px',
    },
    cartItem: {
      display: 'flex',
      padding: '20px',
      borderRadius: '8px',
      marginBottom: '15px',
      boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
      backgroundColor: 'white',
      alignItems: 'center',
    },
    itemImage: {
      width: '100px',
      height: '100px',
      objectFit: 'cover' as 'cover',
      borderRadius: '6px',
      marginRight: '20px',
    },
    itemDetails: {
      flex: '1',
    },
    itemName: {
      fontSize: '18px',
      fontWeight: 'bold',
      marginBottom: '5px',
      color: '#333',
    },
    itemPrice: {
      fontSize: '16px',
      color: '#666',
      marginBottom: '10px',
    },
    quantityControl: {
      display: 'flex',
      alignItems: 'center',
      gap: '10px',
    },
    quantityBtn: {
      width: '30px',
      height: '30px',
      borderRadius: '50%',
      border: 'none',
      backgroundColor: '#f0f0f0',
      cursor: 'pointer',
      fontSize: '16px',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
    },
    quantity: {
      fontSize: '16px',
      fontWeight: 'bold',
    },
    itemTotal: {
      fontSize: '18px',
      fontWeight: 'bold',
      color: '#333',
      marginLeft: '20px',
      minWidth: '80px',
      textAlign: 'right' as 'right',
    },
    removeBtn: {
      backgroundColor: '#ff4d4d',
      color: 'white',
      border: 'none',
      padding: '8px 12px',
      borderRadius: '4px',
      cursor: 'pointer',
      marginLeft: '15px',
    },
    cartSummary: {
      flex: '1 1 25%',
      minWidth: '250px',
      backgroundColor: 'white',
      padding: '20px',
      borderRadius: '8px',
      boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
      alignSelf: 'flex-start',
    },
    summaryTitle: {
      fontSize: '20px',
      fontWeight: 'bold',
      marginBottom: '20px',
      paddingBottom: '10px',
      borderBottom: '1px solid #eee',
    },
    summaryRow: {
